import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nemesis_mobile/app.dart';
import 'package:nemesis_mobile/data/city.dart';
import 'package:nemesis_mobile/data/store.dart';
import 'package:nemesis_mobile/main.dart';
import 'package:nemesis_mobile/routing/native_engine.dart';
import 'package:nemesis_mobile/routing/plan.dart';
import 'package:nemesis_mobile/services.dart';

import 'support.dart';

/// The data of the test APK : the lines of 2023 of Abidjan (H-030), generated by
/// tools/maquette/appli_2023.py. The engine test needs NEMESIS_ROUTING_LIB, like
/// native_engine_test.dart.
void main() {
  final city = CityData.fromJson(
    File('assets/reel/city.json').readAsStringSync(),
  );

  test('the lines of 2023 load, are real and searchable', () {
    expect(city.isFictional, isFalse);
    expect(city.code, 'abidjan');
    expect(city.stops.length, greaterThan(1000));
    expect(city.lines.length, greaterThan(300));
    expect(city.fares, isEmpty, reason: 'pas de prix dans le GTFS 2023');
    expect(city.search('plateau'), isNotEmpty);
    expect(city.search('adjame'), isNotEmpty);
    expect(city.nearestStations(city.position), hasLength(3));
    for (final stop in city.stops) {
      expect(stop.lines, isNotEmpty, reason: stop.code);
    }
  });

  test('the clock of the test APK stays on a weekday of June 2023', () {
    final day = in2023();
    expect(day.year, 2023);
    expect(day.month, 6);
    expect(day.weekday, DateTime.now().weekday);
  });

  final library = Platform.environment['NEMESIS_ROUTING_LIB'];
  test(
    'the engine plans Yopougon to Le Plateau on the lines of 2023',
    () async {
      final engine = NativeRoutingService.open(
        Directory('assets/reel/pack').absolute.path,
        library: library,
      );
      addTearDown(engine.close);
      expect(engine.info()['city'], 'abidjan');
      final plateau = city.search('le plateau').first.point;
      final result = await engine.plan(
        PlanQuery(city.position, plateau, DateTime(2023, 6, 13, 7, 30)),
      );
      expect(result.isFictional, isFalse);
      expect(result.notes, contains('evaluation_only_data'));
      expect(result.options, isNotEmpty);
    },
    skip: library == null ? 'NEMESIS_ROUTING_LIB absent' : null,
  );

  for (final scale in [1.0, 2.0]) {
    testWidgets(
      'the test APK, from home to the steps, real names at ${(scale * 100).round()} %',
      (tester) async {
        await phone(tester, textScale: scale);
        final engine = NativeRoutingService.open(
          Directory('assets/reel/pack').absolute.path,
          library: library,
        );
        addTearDown(engine.close);
        await tester.pumpWidget(
          NemesisApp(
            services: (child) => AppServices(
              city: city,
              mapJson: File('assets/reel/map.json').readAsStringSync(),
              routing: engine,
              store: SqliteStore.inMemory(),
              mapBuilder: mapPlaceholderFor(city),
              now: () => DateTime(2023, 6, 13, 7, 30),
              showFictionalBanner: true,
              storeChanges: ValueNotifier(0),
              child: child,
            ),
          ),
        );
        await tester.pumpAndSettle();
        expect(find.text('LIGNES DE 2023 · À CONFIRMER'), findsWidgets);

        await tester.tap(find.text('Tu vas où ?'));
        await tester.pumpAndSettle();
        await tester.enterText(find.byType(TextField), 'le plateau');
        await tester.pumpAndSettle();
        await tester.tap(find.text('Le Plateau').last);
        // The engine answers from a native call: let real time pass.
        for (var i = 0; i < 40; i++) {
          await tester.runAsync(
            () => Future<void>.delayed(const Duration(milliseconds: 100)),
          );
          await tester.pump(const Duration(milliseconds: 100));
          if (find.textContaining('Prix inconnu').evaluate().isNotEmpty) break;
        }
        expect(find.textContaining(' min'), findsWidgets);
        expect(find.textContaining('Prix inconnu'), findsWidgets);
      },
      skip: library == null, // NEMESIS_ROUTING_LIB absent
    );
  }
}
